-- ----------sql1------------
-- 0
SELECT AVG(HOME_TEAM_GOAL) FROM MATCH JOIN LEAGUE ON MATCH.LEAGUE_ID = LEAGUE.ID JOIN COUNTRY ON LEAGUE.COUNTRY_ID = COUNTRY.ID WHERE COUNTRY.NAME = 'POLAND' AND SEASON = '2010/2011';
-- ----------sql2------------
-- NULL
SELECT CAST(SUM(T2.HOME_TEAM_GOAL) AS REAL) / COUNT(T2.ID) FROM COUNTRY AS T1 INNER JOIN MATCH AS T2 ON T1.ID = T2.COUNTRY_ID WHERE T1.NAME = 'POLAND' AND T2.SEASON = '2010/2011';

