-- ----------sql1------------
-- 20
SELECT COUNT(*) FROM PLAYER_ATTRIBUTES PA JOIN PLAYER P ON PA.PLAYER_API_ID = P.PLAYER_API_ID WHERE P.HEIGHT > 180 AND PA.VOLLEYS > 70;
-- ----------sql2------------
